import { createContext, useContext } from "react";

type ListKeyboardNavContextType = {
  enableKeyboardShortcuts?: boolean;
  handleKeyDown?: (e: React.KeyboardEvent<HTMLElement>) => void;
};

export const ListKeyboardNavContext = createContext<ListKeyboardNavContextType | undefined>(
  undefined,
);

export const useListKeyboardNavContext = () => {
  const context = useContext(ListKeyboardNavContext);
  if (!context) {
    throw new Error("useListKeyboardNavContext must be used within a ListKeyboardNavProvider");
  }
  return context;
};
